import React from 'react';
import { useTranslation } from 'react-i18next';
import './Controls.css';

export default function Controls({
  provinces, selectedProvinces, onChangeProvinces,
  foodTypes, selectedFoodType,   onChangeFoodType,
  dateRange,  onChangeDateRange
}) {
  const { t } = useTranslation();

  const handleProvinceToggle = prov => {
    if (selectedProvinces.includes(prov)) {
      onChangeProvinces(selectedProvinces.filter(p => p !== prov));
    } else {
      onChangeProvinces([...selectedProvinces, prov]);
    }
  };

  return (
    <div className="controls-container">
      <div className="control-group">
        <label>{t('select_food_type')}</label>
        <select
          className="select"
          value={selectedFoodType}
          onChange={e => onChangeFoodType(e.target.value)}
        >
          {foodTypes.map(type => (
            <option key={type} value={type}>{type}</option>
          ))}
        </select>
      </div>

      <div className="control-group">
        <label>{t('select_provinces')}</label>
        <div className="checkbox-group">
          {provinces.map(prov => (
            <label key={prov}>
              <input
                type="checkbox"
                checked={selectedProvinces.includes(prov)}
                onChange={() => handleProvinceToggle(prov)}
              />
              {prov}
            </label>
          ))}
        </div>
      </div>

      <div className="control-group">
        <label>{t('select_date_range')}</label>
        <div style={{ display: 'flex', gap: '0.5rem' }}>
          <input
            className="date-input"
            type="month"
            value={dateRange.start}
            onChange={e => onChangeDateRange({ ...dateRange, start: e.target.value })}
          />
          <span>–</span>
          <input
            className="date-input"
            type="month"
            value={dateRange.end}
            onChange={e => onChangeDateRange({ ...dateRange, end: e.target.value })}
          />
        </div>
      </div>
    </div>
  );
}
